static unsigned checks=0;
static void Check(bool v,const std::string& text){if(!v)throw std::runtime_error(text);++checks;}
static void Near(float a,float b,const std::string& text){Check(std::abs(a-b)<.004f,text);}
static void Same(const TransformComponent& a,const TransformComponent& b){auto x=TransformMatrix(a),y=TransformMatrix(b);for(int i=0;i<16;++i)Near(float(x[i]),float(y[i]),"preview and final World matrices match at "+std::to_string(i)+": "+std::to_string(x[i])+" vs "+std::to_string(y[i]));}
struct Owned{std::filesystem::path path;~Owned(){std::error_code ec;std::filesystem::remove(path,ec);}};
static void Write(const std::filesystem::path& path,const Json& data){std::string error;Check(SceneSerializer::WriteAtomic(path,data,&error,true),error);}
static Entity Named(const World& w,Entity root,const std::string& name){for(auto e:w.Subtree(root))if(auto* t=w.GetComponent<TagComponent>(e);t&&t->name==name)return e;throw std::runtime_error("Missing "+name);}
static std::vector<Vec3> Corners(ResourceManager& rm,const EditorLayer::PlacementPreview& preview){std::vector<Vec3> out;for(const auto& item:preview.items){auto mesh=rm.Get<MeshResource>(item.mesh);Check(mesh&&mesh->IsLoaded(),"preview Mesh available");auto points=PlacementCorners(MeshPlacementBounds(mesh->GetData().meshData),item.transform);out.insert(out.end(),points.begin(),points.end());}return out;}
static void Contact(ResourceManager& rm,const EditorLayer::PlacementPreview& preview,Vec3 point,Vec3 normal){float low=INFINITY;for(auto p:Corners(rm,preview))low=std::min(low,(p.x-point.x)*normal.x+(p.y-point.y)*normal.y+(p.z-point.z)*normal.z);Check(low>=-.004f,"compound bounds never penetrate surface");}
